<?php
require 'delivery_guard.php';
$status=trim($_GET['status']??'');
$allowed=['Charge Pending','Charge Proposed','Charge Accepted','Arrived at Pickup','Picked Up','Completed'];
$where="WHERE d.assigned_delivery_man_id=$deliveryId";
if(in_array($status,$allowed,true)){$statusSafe=mysqli_real_escape_string($conn,$status);$where.=" AND d.status='$statusSafe'";}
$sql="SELECT d.delivery_id,d.status,d.proposed_charge,d.accepted_charge,d.created_at,d.updated_at,d.delivered_at,COALESCE(i.title,wp.title,'Item') AS item_name,i.location AS pickup_location,u.name AS receiver_name FROM deliveries d LEFT JOIN items i ON i.item_id=d.item_id LEFT JOIN transactions t ON d.source_table='transactions' AND t.transaction_id=d.source_request_id LEFT JOIN wanted_offers wo ON wo.offer_id=t.request_id LEFT JOIN wanted_posts wp ON wp.wanted_id=wo.wanted_id LEFT JOIN users u ON u.user_id=d.receiver_id $where ORDER BY d.updated_at DESC,d.delivery_id DESC";
$result=mysqli_query($conn,$sql);$deliveries=[];if($result)while($row=mysqli_fetch_assoc($result))$deliveries[]=$row;
function historyStatusClass($value){return 'status-'.strtolower(str_replace(' ','-',trim($value)));}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delivery History</title><link rel="stylesheet" href="style_delivery.css"></head><body><?php include 'header_sidebar_delivery.php'; ?><main class="main"><section class="delivery-dashboard-heading"><p class="eyebrow">Work record</p><h1>Delivery History</h1><p>Review every delivery you accepted and its latest progress.</p></section><section class="delivery-panel"><form method="get" class="delivery-form-grid"><label>Status<select name="status"><option value="">All statuses</option><?php foreach($allowed as $option): ?><option value="<?php echo htmlspecialchars($option); ?>" <?php echo $status===$option?'selected':''; ?>><?php echo htmlspecialchars($option); ?></option><?php endforeach; ?></select></label><div><button class="request-accept" type="submit">Filter</button> <a class="detail-secondary" href="deliveries.php">Clear</a></div></form></section><section class="recent-requests" style="margin-top:22px"><div class="section-heading"><div><p class="eyebrow">Results</p><h2><?php echo count($deliveries); ?> deliveries</h2></div></div><div class="request-table-wrap"><table class="request-table"><thead><tr><th>Delivery</th><th>Item</th><th>Pickup</th><th>Receiver</th><th>Charge</th><th>Status</th><th>Updated</th></tr></thead><tbody><?php if($deliveries):foreach($deliveries as $delivery): ?><tr><td>#<?php echo (int)$delivery['delivery_id']; ?></td><td><?php echo htmlspecialchars($delivery['item_name']); ?></td><td><?php echo htmlspecialchars($delivery['pickup_location']?:'N/A'); ?></td><td><?php echo htmlspecialchars($delivery['receiver_name']?:'N/A'); ?></td><td><?php $charge=$delivery['accepted_charge']??$delivery['proposed_charge'];echo $charge!==null?number_format((float)$charge,2).' BDT':'—'; ?></td><td><span class="request-status <?php echo historyStatusClass($delivery['status']); ?>"><?php echo htmlspecialchars($delivery['status']); ?></span></td><td><?php echo htmlspecialchars($delivery['delivered_at']?:($delivery['updated_at']?:$delivery['created_at'])); ?></td></tr><?php endforeach;else: ?><tr><td colspan="7" class="empty-state">No delivery records match this filter.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>
